// <auto-generated-like />
// Thin, modern .NET 10+ interop layer for the CCE native library (cce.dll / libcce.so).
// Uses LibraryImport for source generation, AOT-friendliness, and performance.
// Target: .NET 10 (or .NET 8/9 with LibraryImport available).
//
// Build the C library first:
//   make cce_dll
// Then ensure cce.dll (or cce.so) is next to your app or in PATH / LD_LIBRARY_PATH.

using System;
