    // Change if you rename the library or use a different loading strategy.
    private const string LibraryName = "cce";

    static CceNative()
    {
        // Improve P/Invoke reliability: try to load from locations next to this assembly,
        // the current directory, or the app context base directory.
        TryRegisterNativeLibraryResolver();
    }

    private static void TryRegisterNativeLibraryResolver()
    {
        try
        {
            string baseDir = System.AppContext.BaseDirectory;
            string currentDir = Environment.CurrentDirectory;

            // Common locations during development and after `dotnet build/test`
            string[] candidateDirs = {
                baseDir,
                currentDir,
                System.IO.Path.GetFullPath(System.IO.Path.Combine(baseDir, "..")),
                System.IO.Path.GetFullPath(System.IO.Path.Combine(currentDir, "..", "..", "..")),
            };

            foreach (string dir in candidateDirs.Distinct(StringComparer.OrdinalIgnoreCase))
            {
                if (string.IsNullOrEmpty(dir)) continue;

                string dllPath = System.IO.Path.Combine(dir, "cce.dll");
                string soPath = System.IO.Path.Combine(dir, "cce.so");
                string dylibPath = System.IO.Path.Combine(dir, "cce.dylib");

                if (System.IO.File.Exists(dllPath))
                {
                    System.Runtime.InteropServices.NativeLibrary.Load(dllPath);
                    return;
                }
                if (System.IO.File.Exists(soPath))
                {
                    System.Runtime.InteropServices.NativeLibrary.Load(soPath);
                    return;
                }
                if (System.IO.File.Exists(dylibPath))
                {
                    System.Runtime.InteropServices.NativeLibrary.Load(dylibPath);
                    return;
                }
            }

            // Last attempt: explicit load using full known location from repo root relative to current dir
            var possibleRootDll = System.IO.Path.GetFullPath(System.IO.Path.Combine(currentDir, "..", "..", "..", "cce.dll"));
            if (System.IO.File.Exists(possibleRootDll))
            {
                System.Runtime.InteropServices.NativeLibrary.Load(possibleRootDll);
            }
        }
        catch
        {
            // Let the normal P/Invoke search continue
        }
    }

